def main():
  base = Path(__file__).resolve().parent / "src"
  targets = [
      ("x86_64/sse42.rs", x86_common(128)),
      ("x86_64/avx.rs", x86_common(256)),
      ("x86_64/avx512.rs", x86_common(512)),
      ("aarch64/neon.rs", neon_spec()),
      ("wasm32/simd128.rs", wasm_spec()),
  ]
  paths = []
  for rel, spec in targets:
    p = base / rel
    p.write_text(render_isa(spec))
    paths.append(str(p))
  subprocess.run(["cargo", "+nightly", "fmt", "--", *paths], check=True)
  for p in paths:
    assert not re.search(
        r"\bunsafe\b", Path(p).read_text()
    ), f"Found unsafe in {p}"


if __name__ == "__main__":
  main()
